const fs=require("fs");
for (const f of [".github/workflows/deploy.yml",".github/workflows/ci.yml"]) {
  const lines=fs.readFileSync(f,"utf8").split("\n");
  let bad=[];
  lines.forEach((l,i)=>{
    if (l.includes("\t")) bad.push(`tab at ${i+1}`);
    const ind=l.match(/^ */)[0].length;
    if (l.trim() && ind%2) bad.push(`odd indent ${ind} at ${i+1}`);
  });
  const txt=lines.join("\n");
  const need=["name:","on:","jobs:"];
  const miss=need.filter(k=>!new RegExp("^"+k.replace(":","\\:")+"","m").test(txt));
  const uses=[...txt.matchAll(/uses:\s*(\S+)/g)].map(m=>m[1]);
  const unpinned=uses.filter(u=>!u.startsWith("./")&&!u.includes("@") ).concat(uses.filter(u=>u.includes("@")&&!/@[0-9a-f]{40}$/.test(u)));
  console.log(`--- ${f}`);
  console.log("  indentation/tabs:", bad.length?bad.join(", "):"clean");
  console.log("  required keys:", miss.length?"MISSING "+miss.join(","):"present");
  console.log("  actions used:", uses.length, "| unpinned/floating:", unpinned.length?unpinned:"none");
  console.log("  permissions block:", /^permissions:/m.test(txt)?"yes":"NO");
  console.log("  traversal/exfil verbs:", /\b(curl|wget|nc|scp|rsync|zip)\b/.test(txt)?"FOUND":"none");
}
'

